	// \u53D6\u8272\u4E0D\u518D\u538B\u6697\uFF0C\u7EAF\u767D\u5C01\u9762\u7684 L \u80FD\u5230 1.0\uFF0C\u4E58\u5B8C\u5FC5\u987B\u94B3\u4F4F\uFF1A\u8BA9 L \u6EA2\u51FA\u518D\u9760\u672B\u5C3E\u7684
	// RGB \u94B3\u4F4D\u6536\u573A\u4F1A\u9010\u901A\u9053\u524A\u9876\uFF0C\u628A\u8272\u76F8\u4E5F\u4E00\u8D77\u6539\u6389
